import unittest
from counter import bump
class Hidden(unittest.TestCase):
    def test_negative_value(self): self.assertEqual(bump(-7), -6)
    def test_negative_step(self): self.assertEqual(bump(4, -9), -5)
    def test_float(self): self.assertAlmostEqual(bump(.25, .125), .375)
    def test_zero_step(self): self.assertEqual(bump(12, 0), 12)
    def test_large(self): self.assertEqual(bump(10**30, 2), 10**30+2)
